{"command":"cat <<'EOF' > src/main.rs
use std::io::{self, Read, Write};
use std::os::unix::io::AsRawFd;

#[repr(C)]
#[derive(Clone, Copy)]
pub struct Termios {
    pub c_iflag: u32,
    pub c_oflag: u32,
    pub c_cflag: u32,
    pub c_lflag: u32,
    pub c_line: u8,
    pub c_cc: [u8; 32],
    pub c_ispeed: u32,
    pub c_ospeed: u32,
}

unsafe extern "C" {
    pub fn tcgetattr(fd: i32, termios_p: *mut Termios) -> i32;
    pub fn tcsetattr(fd: i32, optional_actions: i32, termios_p: *const Termios) -> i32;
    pub fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TCSAFLUSH: i32 = 2;
const TCGETS: u64 = 0x5401;
const TIOCGWINSZ: u64 = 0x5413;

const IXON: u32 = 0x400;
const ICRNL: u32 = 0x100;
const BRKINT: u32 = 0x2;
const INPCK: u32 = 0x10;
const ISTRIP: u32 = 0x20;
const OPOST: u32 = 0x1;
const CS8: u32 = 0x30;
const ECHO: u32 = 0x8;
const ICANON: u32 = 0x2;
const ISIG: u32 = 0x1;
const IEXTEN: u32 = 0x8000;
const VMIN: usize = 6;
const VTIME: usize = 5;

struct RawMode {
    original_termios: Termios,
}

impl RawMode {
    fn enable() -> io::Result<Self> {
        let mut termios = unsafe { std::mem::zeroed() };
        if unsafe { tcgetattr(0, &mut termios) } != 0 {
            return Err(io::Error::last_os_error());
        }
        let original_termios = termios;

        termios.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        termios.c_oflag &= !(OPOST);
        termios.c_cflag |= CS8;
        termios.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        termios.c_cc[VMIN] = 0;
        termios.c_cc[VTIME] = 1;

        if unsafe { tcsetattr(0, TCSAFLUSH, &termios) } != 0 {
            return Err(io::Error::last_os_error());
        }

        Ok(RawMode { original_termios })
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        unsafe { tcsetattr(0, TCSAFLUSH, &self.original_termios) };
    }
}

fn main() -> io::Result<()> {
    let _raw_mode = RawMode::enable()?;
    print!("\x1b[2J\x1b[H");
    io::stdout().flush()?;

    let mut buf = [0u8; 1];
    while io::stdin().read_exact(&mut buf).is_ok() {
        let c = buf[0];
        if c == b'q' & 0x1f {
            break;
        }
        if c.is_ascii_control() {
            print!("{:?}\r\n", c);
        } else {
            print!("{:?} ({:?})\r\n", c as char, c);
        }
        io::stdout().flush()?;
    }

    Ok(())
}
EOF
cargo run
"}

