{"command":"cat <<'EOF' >> src/main.rs

struct Row {
    chars: String,
    render: String,
    hl: Vec<Highlight>,
    hl_open_comment: bool,
}

impl Row {
    fn new(chars: String) -> Self {
        let mut row = Row {
            chars,
            render: String::new(),
            hl: Vec::new(),
            hl_open_comment: false,
        };
        row.update_render();
        row
    }

    fn update_render(&mut self) {
        let mut render = String::new();
        for c in self.chars.chars() {
            if c == '\t' {
                render.push(' ');
                while render.len() % 8 != 0 {
                    render.push(' ');
                }
            } else {
                render.push(c);
            }
        }
        self.render = render;
    }
}

enum Action {
    Insert(usize, usize, String), // x, y, string
    Delete(usize, usize, String), // x, y, string
    InsertLine(usize, String),
    DeleteLine(usize, String),
    SplitLine(usize, usize),
    JoinLines(usize, usize),
}

struct Buffer {
    filename: Option<String>,
    lines: Vec<Row>,
    cx: usize,
    cy: usize,
    row_off: usize,
    col_off: usize,
    modified: bool,
    syntax: Option<&'static Syntax>,
    undo_stack: Vec<Vec<Action>>,
    redo_stack: Vec<Vec<Action>>,
    current_undo_group: Vec<Action>,
}

struct Editor {
    buffers: Vec<Buffer>,
    current_idx: usize,
    rows: u16,
    cols: u16,
    status_msg: String,
    status_msg_time: Instant,
    raw_mode: RawMode,
}

struct RawMode {
    original_termios: Termios,
}

impl RawMode {
    fn enable() -> io::Result<Self> {
        let mut termios = unsafe { std::mem::zeroed() };
        if unsafe { tcgetattr(0, &mut termios) } != 0 {
            return Err(io::Error::last_os_error());
        }
        let original_termios = termios;

        termios.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        termios.c_oflag &= !(OPOST);
        termios.c_cflag |= CS8;
        termios.c_lflag &= !(ECHO | ICANON | IEXTEN | ISIG);
        termios.c_cc[VMIN] = 0;
        termios.c_cc[VTIME] = 1;

        if unsafe { tcsetattr(0, TCSAFLUSH, &termios) } != 0 {
            return Err(io::Error::last_os_error());
        }

        Ok(RawMode { original_termios })
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        unsafe { tcsetattr(0, TCSAFLUSH, &self.original_termios) };
    }
}

impl Buffer {
    fn new(filename: Option<String>) -> Self {
        let mut b = Buffer {
            filename,
            lines: Vec::new(),
            cx: 0,
            cy: 0,
            row_off: 0,
            col_off: 0,
            modified: false,
            syntax: None,
            undo_stack: Vec::new(),
            redo_stack: Vec::new(),
            current_undo_group: Vec::new(),
        };
        b.select_syntax();
        if let Some(ref name) = b.filename {
            if let Ok(file) = File::open(name) {
                let reader = BufReader::new(file);
                for line in reader.lines() {
                    if let Ok(l) = line {
                        b.lines.push(Row::new(l));
                    }
                }
            }
        }
        if b.lines.is_empty() {
            b.lines.push(Row::new(String::new()));
        }
        b.update_all_hl();
        b
    }

    fn select_syntax(&mut self) {
        if let Some(ref name) = self.filename {
            for s in SYNTAX_DB {
                for ext in s.extensions {
                    if name.ends_with(ext) {
                        self.syntax = Some(s);
                        return;
                    }
                }
            }
        }
        self.syntax = None;
    }

    fn update_hl(&mut self, idx: usize) -> bool {
        if idx >= self.lines.len() { return false; }
        let syntax = if let Some(s) = self.syntax { s } else {
            let row = &mut self.lines[idx];
            row.hl = vec![Highlight::Normal; row.render.len()];
            return false;
        };

        let mut hl = Vec::new();
        let chars: Vec<char> = self.lines[idx].render.chars().collect();
        let mut i = 0;
        let mut in_string = None;
        let prev_open_comment = if idx > 0 { self.lines[idx-1].hl_open_comment } else { false };
        let mut in_comment = prev_open_comment;

        while i < chars.len() {
            let c = chars[i];
            let prev_hl = if i > 0 { hl[i-1] } else { Highlight::Normal };

            // Multi-line comment
            if in_comment {
                hl.push(Highlight::MultiLineComment);
                if let Some(end) = syntax.multi_line_comment_end {
                    let end_chars: Vec<char> = end.chars().collect();
                    if i + end_chars.len() <= chars.len() && chars[i..i+end_chars.len()] == end_chars[..] {
                        for _ in 1..end_chars.len() {
                            hl.push(Highlight::MultiLineComment);
                            i += 1;
                        }
                        in_comment = false;
                    }
                }
                i += 1;
                continue;
            }

            // Single-line comment
            if let Some(start) = syntax.single_line_comment_start {
                let start_chars: Vec<char> = start.chars().collect();
                if i + start_chars.len() <= chars.len() && chars[i..i+start_chars.len()] == start_chars[..] {
                    for _ in i..chars.len() {
                        hl.push(Highlight::Comment);
                    }
                    i = chars.len();
                    continue;
                }
            }

            // Start of multi-line comment
            if let Some(start) = syntax.multi_line_comment_start {
                let start_chars: Vec<char> = start.chars().collect();
                if i + start_chars.len() <= chars.len() && chars[i..i+start_chars.len()] == start_chars[..] {
                    for _ in 0..start_chars.len() {
                        hl.push(Highlight::MultiLineComment);
                        i += 1;
                    }
                    in_comment = true;
                    continue;
                }
            }

            // Strings
            if let Some(quote) = in_string {
                hl.push(Highlight::String);
                if c == '\\' && i + 1 < chars.len() {
                    hl.push(Highlight::String);
                    i += 2;
                    continue;
                }
                if c == quote {
                    in_string = None;
                }
                i += 1;
                continue;
            } else if c == '"' || c == '\'' {
                in_string = Some(c);
                hl.push(Highlight::String);
                i += 1;
                continue;
            }

            // Numbers
            if c.is_digit(10) && (i == 0 || !chars[i-1].is_alphanumeric() && chars[i-1] != '.') || (c == '.' && i > 0 && chars[i-1].is_digit(10)) {
                hl.push(Highlight::Number);
                i += 1;
                continue;
            }

            // Keywords
            if i == 0 || !chars[i-1].is_alphanumeric() {
                let mut found = false;
                for kw in syntax.keywords1 {
                    let kw_chars: Vec<char> = kw.chars().collect();
                    if i + kw_chars.len() <= chars.len() && chars[i..i+kw_chars.len()] == kw_chars[..] {
                        if i + kw_chars.len() == chars.len() || !chars[i+kw_chars.len()].is_alphanumeric() {
                            for _ in 0..kw_chars.len() {
                                hl.push(Highlight::Keyword1);
                            }
                            i += kw_chars.len();
                            found = true;
                            break;
                        }
                    }
                }
                if found { continue; }
                for kw in syntax.keywords2 {
                    let kw_chars: Vec<char> = kw.chars().collect();
                    if i + kw_chars.len() <= chars.len() && chars[i..i+kw_chars.len()] == kw_chars[..] {
                        if i + kw_chars.len() == chars.len() || !chars[i+kw_chars.len()].is_alphanumeric() {
                            for _ in 0..kw_chars.len() {
                                hl.push(Highlight::Keyword2);
                            }
                            i += kw_chars.len();
                            found = true;
                            break;
                        }
                    }
                }
                if found { continue; }
            }

            hl.push(Highlight::Normal);
            i += 1;
        }

        let changed = self.lines[idx].hl_open_comment != in_comment;
        self.lines[idx].hl = hl;
        self.lines[idx].hl_open_comment = in_comment;
        changed
    }

    fn update_all_hl(&mut self) {
        let mut i = 0;
        while i < self.lines.len() {
            self.update_hl(i);
            i += 1;
        }
    }
}
EOF
"}

