impl Editor {
    fn buf(&self) -> &Buffer { &self.buffers[self.current_idx] }
    fn buf_mut(&mut self) -> &mut Buffer { &mut self.buffers[self.current_idx] }

    fn refresh_screen(&mut self) -> io::Result<()> {
        self.scroll();
        let mut out = Vec::new();
        out.write_all(b"\x1b[?25l\x1b[H")?;
        for y in 0..self.rows {
            let file_row = y as usize + self.buf().row_off;
            if file_row >= self.buf().lines.len() {
                if self.buf().lines.len() == 1 && self.buf().lines[0].chars.is_empty() && y == self.rows / 3 {
                    let wel = "Kiro editor -- version 0.4.3";
                    let mut padding = (self.cols as usize - wel.len()) / 2;
                    if padding > 0 { out.write_all(b"\x1b[37m~\x1b[39m"); padding -= 1; }
                    for _ in 0..padding { out.write_all(b" "); }
                    out.write_all(wel.as_bytes())?;
                } else { out.write_all(b"\x1b[37m~\x1b[39m")?; }
            } else {
                let row = &self.buf().lines[file_row];
                let mut len = row.render.chars().count();
                if len > self.buf().col_off {
                    let start = self.buf().col_off;
                    let end = std::cmp::min(start + self.cols as usize, len);
                    let mut cur_hl = Highlight::Normal;
                    let chars: Vec<char> = row.render.chars().collect();
                    for i in start..end {
                        let h = row.hl.get(i).copied().unwrap_or(Highlight::Normal);
                        if h != cur_hl { out.write_all(self.hl_color(h))?; cur_hl = h; }
                        out.write_all(chars[i].to_string().as_bytes())?;
                    }
                    out.write_all(b"\x1b[39m\x1b[49m")?;
                }
            }
            out.write_all(b"\x1b[K\r\n")?;
        }
        // Status bar
        out.write_all(b"\x1b[7m")?;
        let status = format!("\"{}\" - {}/{} {}", self.buf().filename.as_deref().unwrap_or("[No Name]"), self.current_idx+1, self.buffers.len(), if self.buf().modified {"(modified)"} else {""});
        let pos = format!("{} {}/{}", self.buf().syntax.map(|s| s.file_type).unwrap_or("plain"), self.buf().cy+1, self.buf().lines.len());
        let mut slen = status.len();
        out.write_all(status.as_bytes())?;
        while slen < self.cols as usize {
            if self.cols as usize - slen == pos.len() { out.write_all(pos.as_bytes())?; break; }
            out.write_all(b" ")?; slen += 1;
        }
        out.write_all(b"\x1b[0m\r\n\x1b[K")?;
        if Instant::now().duration_since(self.status_msg_time) < Duration::from_secs(5) {
            out.write_all(self.status_msg.as_bytes())?;
        } else { out.write_all(b"Ctrl-? for help")?; }
        let cx = self.buf().render_cx() - self.buf().col_off + 1;
        let cy = self.buf().cy - self.buf().row_off + 1;
        out.write_all(format!("\x1b[{};{}H\x1b[?25h", cy, cx).as_bytes())?;
        io::stdout().write_all(&out)?; io::stdout().flush()?;
        Ok(())
    }

    fn hl_color(&self, hl: Highlight) -> &[u8] {
        match hl {
