        r.update_render();
        r
    }
    fn update_render(&mut self) {
        let mut res = String::new();
        for c in self.chars.chars() {
            if c == '\t' {
                res.push(' ');
                while res.len() % 8 != 0 { res.push(' '); }
            } else { res.push(c); }
        }
        self.render = res;
    }
}

struct Buffer {
    filename: Option<String>,
    lines: Vec<Row>,
