        b.select_syntax();
        b.update_all_hl();
        b
    }
    fn select_syntax(&mut self) {
        if let Some(ref name) = self.filename {
            for s in SYNTAX_DB {
                for ext in s.extensions { if name.ends_with(ext) { self.syntax = Some(s); return; } }
            }
        }
