    }
    fn update_render(&mut self) {
        let mut res = String::new();
        for c in self.chars.chars() {
            if c == '\t' {
                res.push(' ');
                while res.len() % 8 != 0 { res.push(' '); }
            } else { res.push(c); }
        }
        self.render = res;
    }
}

struct Buffer {
    filename: Option<String>,
    lines: Vec<Row>,
    cx: usize, cy: usize,
    row_off: usize, col_off: usize,
    modified: bool,
    syntax: Option<&'static Syntax>,
}

impl Buffer {
    fn new(filename: Option<String>) -> Self {
        let mut b = Buffer { filename: filename.clone(), lines: Vec::new(), cx: 0, cy: 0, row_off: 0, col_off: 0, modified: false, syntax: None };
        if let Some(ref name) = filename {
            if let Ok(f) = File::open(name) {
                let reader = BufReader::new(f);
                for line in reader.lines() { if let Ok(l) = line { b.lines.push(Row::new(l)); } }
            }
        }
        if b.lines.is_empty() { b.lines.push(Row::new(String::new())); }
        b.select_syntax();
        b.update_all_hl();
        b
    }
    fn select_syntax(&mut self) {
        if let Some(ref name) = self.filename {
            for s in SYNTAX_DB {
                for ext in s.extensions { if name.ends_with(ext) { self.syntax = Some(s); return; } }
            }
        }
        self.syntax = None;
    }
    fn update_hl(&mut self, idx: usize) -> bool {
        if idx >= self.lines.len() { return false; }
        let syntax = if let Some(s) = self.syntax { s } else {
            let row = &mut self.lines[idx];
            row.hl = vec![Highlight::Normal; row.render.len()];
            return false;
        };
        let prev_open_comment = if idx > 0 { self.lines[idx-1].hl_open_comment } else { false };
        let mut hl = Vec::new();
        let chars: Vec<char> = self.lines[idx].render.chars().collect();
        let mut i = 0;
        let mut in_string = None;
        let mut in_comment = prev_open_comment;
        while i < chars.len() {
            let c = chars[i];
            if in_comment {
                hl.push(Highlight::MultiLineComment);
                if let Some(end) = syntax.multi_line_comment_end {
                    if self.lines[idx].render[i..].starts_with(end) {
                        for _ in 1..end.len() { hl.push(Highlight::MultiLineComment); i += 1; }
                        in_comment = false;
                    }
                }
                i += 1; continue;
            }
            if let Some(start) = syntax.single_line_comment_start {
                if self.lines[idx].render[i..].starts_with(start) {
                    for _ in i..chars.len() { hl.push(Highlight::Comment); }
                    i = chars.len(); continue;
                }
            }
            if let Some(start) = syntax.multi_line_comment_start {
                if self.lines[idx].render[i..].starts_with(start) {
                    for _ in 0..start.len() { hl.push(Highlight::MultiLineComment); i += 1; }
                    in_comment = true; i -= 1; // back one to re-process current in comment mode
                    i += 1; continue;
                }
            }
            if let Some(quote) = in_string {
                hl.push(Highlight::String);
                if c == '\\' && i + 1 < chars.len() { hl.push(Highlight::String); i += 2; continue; }
                if c == quote { in_string = None; }
                i += 1; continue;
            } else if c == '"' || c == '\'' {
                in_string = Some(c); hl.push(Highlight::String); i += 1; continue;
            }
            if (c.is_digit(10) && (i == 0 || !chars[i-1].is_alphanumeric() && chars[i-1] != '.')) || (c == '.' && i > 0 && chars[i-1].is_digit(10)) {
                hl.push(Highlight::Number); i += 1; continue;
            }
            if i == 0 || !chars[i-1].is_alphanumeric() {
                let mut found = false;
                for kw in syntax.keywords1 {
                    if self.lines[idx].render[i..].starts_with(kw) {
                        let end = i + kw.len();
                        if end == chars.len() || !chars[end].is_alphanumeric() {
                            for _ in 0..kw.len() { hl.push(Highlight::Keyword1); }
                            i += kw.len(); found = true; break;
                        }
                    }
                }
                if found { continue; }
                for kw in syntax.keywords2 {
                    if self.lines[idx].render[i..].starts_with(kw) {
                        let end = i + kw.len();
                        if end == chars.len() || !chars[end].is_alphanumeric() {
                            for _ in 0..kw.len() { hl.push(Highlight::Keyword2); }
                            i += kw.len(); found = true; break;
                        }
                    }
                }
                if found { continue; }
            }
            hl.push(Highlight::Normal); i += 1;
        }
        let changed = self.lines[idx].hl_open_comment != in_comment;
        self.lines[idx].hl = hl;
        self.lines[idx].hl_open_comment = in_comment;
        changed
    }
    fn update_all_hl(&mut self) {
        let mut i = 0;
        while i < self.lines.len() {
            if self.update_hl(i) { /* could propagate to next line but simple for now */ }
            i += 1;
        }
    }
}

struct Editor {
    buffers: Vec<Buffer>,
    current_idx: usize,
    rows: u16, cols: u16,
    status_msg: String,
    status_msg_time: Instant,
    raw_mode: RawMode,
}

impl Editor {
    fn buf(&self) -> &Buffer { &self.buffers[self.current_idx] }
    fn buf_mut(&mut self) -> &mut Buffer { &mut self.buffers[self.current_idx] }

    fn refresh_screen(&mut self) -> io::Result<()> {
        self.scroll();
        let mut out = Vec::new();
        out.write_all(b"\x1b[?25l\x1b[H")?;
        for y in 0..self.rows {
            let file_row = y as usize + self.buf().row_off;
            if file_row >= self.buf().lines.len() {
                if self.buf().lines.len() == 1 && self.buf().lines[0].chars.is_empty() && y == self.rows / 3 {
                    let wel = "Kiro editor -- version 0.4.3";
                    let mut padding = (self.cols as usize - wel.len()) / 2;
                    if padding > 0 { out.write_all(b"\x1b[37m~\x1b[39m"); padding -= 1; }
                    for _ in 0..padding { out.write_all(b" "); }
                    out.write_all(wel.as_bytes())?;
                } else { out.write_all(b"\x1b[37m~\x1b[39m")?; }
            } else {
                let row = &self.buf().lines[file_row];
                let mut len = row.render.chars().count();
                if len > self.buf().col_off {
                    let start = self.buf().col_off;
                    let end = std::cmp::min(start + self.cols as usize, len);
                    let mut cur_hl = Highlight::Normal;
                    let chars: Vec<char> = row.render.chars().collect();
                    for i in start..end {
                        let h = row.hl.get(i).copied().unwrap_or(Highlight::Normal);
                        if h != cur_hl { out.write_all(self.hl_color(h))?; cur_hl = h; }
                        out.write_all(chars[i].to_string().as_bytes())?;
                    }
                    out.write_all(b"\x1b[39m\x1b[49m")?;
                }
            }
            out.write_all(b"\x1b[K\r\n")?;
        }
        // Status bar
        out.write_all(b"\x1b[7m")?;
        let status = format!("\"{}\" - {}/{} {}", self.buf().filename.as_deref().unwrap_or("[No Name]"), self.current_idx+1, self.buffers.len(), if self.buf().modified {"(modified)"} else {""});
        let pos = format!("{} {}/{}", self.buf().syntax.map(|s| s.file_type).unwrap_or("plain"), self.buf().cy+1, self.buf().lines.len());
        let mut slen = status.len();
        out.write_all(status.as_bytes())?;
        while slen < self.cols as usize {
            if self.cols as usize - slen == pos.len() { out.write_all(pos.as_bytes())?; break; }
            out.write_all(b" ")?; slen += 1;
        }
        out.write_all(b"\x1b[0m\r\n\x1b[K")?;
        if Instant::now().duration_since(self.status_msg_time) < Duration::from_secs(5) {
            out.write_all(self.status_msg.as_bytes())?;
        } else { out.write_all(b"Ctrl-? for help")?; }
        let cx = self.buf().render_cx() - self.buf().col_off + 1;
        let cy = self.buf().cy - self.buf().row_off + 1;
        out.write_all(format!("\x1b[{};{}H\x1b[?25h", cy, cx).as_bytes())?;
        io::stdout().write_all(&out)?; io::stdout().flush()?;
        Ok(())
    }

    fn hl_color(&self, hl: Highlight) -> &[u8] {
        match hl {
            Highlight::Normal => b"\x1b[39m",
            Highlight::Comment | Highlight::MultiLineComment => b"\x1b[90m",
            Highlight::Keyword1 => if matches!(self.buf().syntax.map(|s| s.file_type), Some("rust") | Some("python")) { b"\x1b[94m" } else { b"\x1b[33m" },
            Highlight::Keyword2 => if matches!(self.buf().syntax.map(|s| s.file_type), Some("rust") | Some("python")) { b"\x1b[93m" } else { b"\x1b[91m" },
            Highlight::String => b"\x1b[32m",
            Highlight::Number => b"\x1b[95m",
            Highlight::Match => b"\x1b[30m\x1b[103m",
            Highlight::CurrentMatch => b"\x1b[30m\x1b[107m",
        }
    }

    fn scroll(&mut self) {
        let rcx = self.buf().render_cx();
        if self.buf().cy < self.buf().row_off { self.buf_mut().row_off = self.buf().cy; }
        if self.buf().cy >= self.buf().row_off + self.rows as usize { self.buf_mut().row_off = self.buf().cy - self.rows as usize + 1; }
        if rcx < self.buf().col_off { self.buf_mut().col_off = rcx; }
        if rcx >= self.buf().col_off + self.cols as usize { self.buf_mut().col_off = rcx - self.cols as usize + 1; }
    }
}

impl Buffer {
    fn render_cx(&self) -> usize {
        let mut x = 0;
        for c in self.lines[self.cy].chars.chars().take(self.cx) {
            if c == '\t' { x += 8 - (x % 8); } else { x += 1; }
        }
        x
    }
}

fn read_key() -> Key {
    let mut b = [0u8; 1];
    if io::stdin().read_exact(&mut b).is_err() { return Key::Unknown; }
    if b[0] == 0x1b {
        let mut next = [0u8; 1];
        if io::stdin().read_exact(&mut next).is_err() { return Key::Esc; }
        if next[0] == b'[' {
            let mut seq = [0u8; 2];
            if io::stdin().read_exact(&mut seq[0..1]).is_err() { return Key::Unknown; }
            if seq[0] >= b'0' && seq[0] <= b'9' {
                if io::stdin().read_exact(&mut seq[1..2]).is_err() { return Key::Unknown; }
                if seq[1] == b'~' {
                    match seq[0] { b'1'|b'7' => return Key::Home, b'3' => return Key::Delete, b'4'|b'8' => return Key::End, b'5' => return Key::PageUp, b'6' => return Key::PageDown, _ => {} }
                }
            } else {
                match seq[0] { b'A' => return Key::Up, b'B' => return Key::Down, b'C' => return Key::Right, b'D' => return Key::Left, b'H' => return Key::Home, b'F' => return Key::End, _ => {} }
            }
        } else { return Key::Alt(next[0] as char); }
    } else if b[0] == 0x7f { return Key::Backspace; }
    else if b[0] < 32 { return Key::Ctrl((b[0] + b'@') as char); }
    else {
        let mut bytes = vec![b[0]];
        let len = if b[0] < 0x80 { 1 } else if b[0] < 0xe0 { 2 } else if b[0] < 0xf0 { 3 } else { 4 };
        for _ in 1..len { let mut n = [0u8; 1]; if io::stdin().read_exact(&mut n).is_ok() { bytes.push(n[0]); } }
        if let Ok(s) = String::from_utf8(bytes) { if let Some(c) = s.chars().next() { return Key::Char(c); } }
    }
    Key::Unknown
}

