            Key::Left|Key::Ctrl('B') => if self.buf().cx > 0 { self.buf_mut().cx -= 1; } else if self.buf().cy > 0 { self.buf_mut().cy -= 1; self.buf_mut().cx = self.buf().lines[self.buf().cy].chars.chars().count(); }
