    }
}

fn read_key() -> Key {
    let mut b = [0u8; 1]; if io::stdin().read_exact(&mut b).is_err() { return Key::Unknown; }
    if b[0] == 0x1b {
        let mut n = [0u8; 1]; if io::stdin().read_exact(&mut n).is_err() { return Key::Esc; }
        if n[0] == b'[' {
            let mut s = [0u8; 2]; if io::stdin().read_exact(&mut s[0..1]).is_err() { return Key::Unknown; }
            if s[0] >= b'0' && s[0] <= b'9' {
                if io::stdin().read_exact(&mut s[1..2]).is_err() { return Key::Unknown; }
                if s[1] == b'~' { match s[0] { b'1'|b'7' => Key::Home, b'3' => Key::Delete, b'4'|b'8' => Key::End, b'5' => Key::PageUp, b'6' => Key::PageDown, _ => Key::Unknown } } else { Key::Unknown }
            } else { match s[0] { b'A' => Key::Up, b'B' => Key::Down, b'C' => Key::Right, b'D' => Key::Left, b'H' => Key::Home, b'F' => Key::End, _ => Key::Unknown } }
        } else { match n[0] { b'x' => Key::Alt('x'), b'v' => Key::Alt('v'), b'<' => Key::Alt('<'), b'>' => Key::Alt('>'), b'f' => Key::Alt('f'), b'b' => Key::Alt('b'), b'n' => Key::Alt('n'), b'p' => Key::Alt('p'), _ => Key::Alt(n[0] as char) } }
    } else if b[0] == 0x7f { Key::Backspace }
    else if b[0] < 32 { Key::Ctrl((b[0] + b'@') as char) }
    else {
        let mut bs = vec![b[0]];
        let l = if b[0]<0x80 { 1 } else if b[0]<0xe0 { 2 } else if b[0]<0xf0 { 3 } else { 4 };
        for _ in 1..l { let mut n = [0u8; 1]; if io::stdin().read_exact(&mut n).is_ok() { bs.push(n[0]); } }
        if let Ok(s) = String::from_utf8(bs) { if let Some(c) = s.chars().next() { return Key::Char(c); } }
        Key::Unknown
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut buffers = Vec::new();
    if args.is_empty() { buffers.push(Buffer::new(None)); } else { for a in args { buffers.push(Buffer::new(Some(a))); } }
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    unsafe { ioctl(1, TIOCGWINSZ, &mut ws) };
    let mut ed = Editor { buffers, cur: 0, rows: ws.ws_row - 2, cols: ws.ws_col, msg: String::new(), msg_t: Instant::now(), raw: RawMode::enable() };
    loop {
        ed.refresh().ok(); let k = read_key();
        match k {
            Key::Ctrl('Q') => break,
            Key::Ctrl('P')|Key::Ctrl('N')|Key::Ctrl('B')|Key::Ctrl('F')|Key::Up|Key::Down|Key::Left|Key::Right|Key::Home|Key::End|Key::Ctrl('A')|Key::Ctrl('E') => ed.move_cursor(k),
            Key::Char(c) => ed.insert_char(c), Key::Backspace => ed.delete_char(),
            Key::Ctrl('X') => ed.cur = (ed.cur + 1) % ed.buffers.len(),
            Key::Alt('x') => ed.cur = (ed.cur + ed.buffers.len() - 1) % ed.buffers.len(),
            Key::Ctrl('L') => {},
            _ => {}
        }
    }
}
