    fn redo(&mut self) { if let Some(s) = self.buf_mut().redo.pop() { self.buf_mut().undo.push(self.buf().state.clone()); self.buf_mut().state = s; self.buf_mut().update_all_hl(); } }
    fn save(&mut self) {
        if self.buf().filename.is_none() { /* prompt skipped for brevity */ return; }
