fn read_key() -> Key {
    let mut b = [0u8; 1]; if io::stdin().read_exact(&mut b).is_err() { return Key::Unknown; }
    if b[0] == 0x1b {
        let mut n = [0u8; 1]; if io::stdin().read_exact(&mut n).is_err() { return Key::Esc; }
        if n[0] == b'[' {
            let mut s = [0u8; 2]; if io::stdin().read_exact(&mut s[0..1]).is_err() { return Key::Unknown; }
            if s[0] >= b'0' && s[0] <= b'9' { if io::stdin().read_exact(&mut s[1..2]).is_err() { return Key::Unknown; } if s[1] == b'~' { match s[0] { b'1'|b'7' => Key::Home, b'3' => Key::Delete, b'4'|b'8' => Key::End, b'5' => Key::PageUp, b'6' => Key::PageDown, _ => Key::Unknown } } else { Key::Unknown } }
            else { match s[0] { b'A' => Key::Up, b'B' => Key::Down, b'C' => Key::Right, b'D' => Key::Left, b'H' => Key::Home, b'F' => Key::End, _ => Key::Unknown } }
        } else { Key::Alt(n[0] as char) }
    } else if b[0] == 0x7f { Key::Backspace } else if b[0] < 32 { Key::Ctrl((b[0] + b'@') as char) }
    else {
