        for _ in 1..l { let mut n = [0u8; 1]; if io::stdin().read_exact(&mut n).is_ok() { bs.push(n[0]); } }
        if let Ok(s) = String::from_utf8(bs) { if let Some(c) = s.chars().next() { return Key::Char(c); } } Key::Unknown
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect(); let mut buffers = Vec::new();
    if args.is_empty() { buffers.push(Buffer::new(None)); } else { for a in args { if a == "--help" || a == "-h" { println!("./executable: A tiny UTF-8 terminal text editor..."); return; } if a == "--version" || a == "-v" { println!("0.4.3"); return; } buffers.push(Buffer::new(Some(a))); } }
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 }; unsafe { ioctl(1, TIOCGWINSZ, &mut ws) };
    let mut ed = Editor { buffers, cur: 0, rows: ws.ws_row - 2, cols: ws.ws_col, msg: String::new(), msg_t: Instant::now(), raw: RawMode::enable() };
    loop {
        ed.refresh().ok(); let k = read_key();
        match k {
            Key::Ctrl('Q') => break, Key::Char(c) => ed.insert_char(c), Key::Backspace => ed.delete_char(), Key::Ctrl('S') => ed.save(), Key::Ctrl('U') => ed.undo(), Key::Ctrl('R') => ed.redo(),
            Key::Ctrl('X') => ed.cur = (ed.cur + 1) % ed.buffers.len(), Key::Alt('x') => ed.cur = (ed.cur + ed.buffers.len() - 1) % ed.buffers.len(),
            _ => ed.move_cursor(k),
        }
    }
}
