                for kw in syntax.keywords2 { if s.starts_with(kw) && (kw.len() == s.len() || !rchars[i+kw.len()].is_alphanumeric()) { for _ in 0..kw.len() { hl.push(Highlight::Keyword2); } i += kw.len(); found = true; break; } }
