impl Editor {
    fn buf(&self) -> &Buffer { &self.buffers[self.cur] }
    fn buf_mut(&mut self) -> &mut Buffer { &mut self.buffers[self.cur] }
    fn scroll(&mut self) {
        let rcx = self.buf().render_cx();
        if self.buf().state.cy < self.buf().row_off { self.buf_mut().row_off = self.buf().state.cy; }
        if self.buf().state.cy >= self.buf().row_off + self.rows as usize { self.buf_mut().row_off = self.buf().state.cy - self.rows as usize + 1; }
        if rcx < self.buf().col_off { self.buf_mut().col_off = rcx; }
