    }
    fn refresh(&mut self) -> io::Result<()> {
        self.scroll(); let mut out = Vec::new(); out.write_all(b"\x1b[?25l\x1b[H")?;
        for y in 0..self.rows {
            let fr = y as usize + self.buf().row_off;
            if fr >= self.buf().state.lines.len() {
                if self.buf().state.lines.len() == 1 && self.buf().state.lines[0].chars.is_empty() && y == self.rows/3 {
                    let w = "Kiro editor -- version 0.4.3"; let mut p = (self.cols as usize - w.len()) / 2;
