        if help { println!("./executable: A tiny UTF-8 terminal text editor..."); return; }
        for a in args { buffers.push(Buffer::new(Some(a))); }
    }
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 }; unsafe { ioctl(1, TIOCGWINSZ, &mut ws) };
    let mut ed = Editor { buffers, cur: 0, rows: ws.ws_row - 2, cols: ws.ws_col, msg: String::new(), msg_t: Instant::now(), _raw: RawMode::enable() };
