        let syntax = if let Some(s) = self.syntax { s } else { let row = &mut self.state.lines[idx]; row.hl = vec![Highlight::Normal; row.render.chars().count()]; return false; };
        let prev_open = if idx > 0 { self.state.lines[idx-1].hl_open_comment } else { false };
        let mut hl = Vec::new(); let rchars: Vec<char> = self.state.lines[idx].render.chars().collect();
        let mut i = 0; let mut in_str = None; let mut in_comm = prev_open;
        while i < rchars.len() {
            let c = rchars[i];
            if in_comm { hl.push(Highlight::MultiLineComment); if let Some(end) = syntax.multi_line_comment_end { let s: String = rchars[i..].iter().collect(); if s.starts_with(end) { for _ in 1..end.len() { hl.push(Highlight::MultiLineComment); i += 1; } in_comm = false; } } i += 1; continue; }
            if let Some(st) = syntax.single_line_comment_start { let s: String = rchars[i..].iter().collect(); if s.starts_with(st) { while i < rchars.len() { hl.push(Highlight::Comment); i += 1; } break; } }
            if let Some(st) = syntax.multi_line_comment_start { let s: String = rchars[i..].iter().collect(); if s.starts_with(st) { for _ in 0..st.len() { hl.push(Highlight::MultiLineComment); i += 1; } in_comm = true; i -= 1; i += 1; continue; } }
            if let Some(q) = in_str { hl.push(Highlight::String); if c == '\\' && i+1 < rchars.len() { hl.push(Highlight::String); i += 2; continue; } if c == q { in_str = None; } i += 1; continue; } else if c == '"' || c == '\'' { in_str = Some(c); hl.push(Highlight::String); i += 1; continue; }
            if c.is_digit(10) && (i == 0 || !rchars[i-1].is_alphanumeric() && rchars[i-1] != '.') || (c == '.' && i > 0 && rchars[i-1].is_digit(10)) { hl.push(Highlight::Number); i += 1; continue; }
            if i == 0 || !rchars[i-1].is_alphanumeric() {
                let s: String = rchars[i..].iter().collect(); let mut found = false;
                for kw in syntax.keywords1 { if s.starts_with(kw) && (kw.len() == s.len() || !rchars[i+kw.len()].is_alphanumeric()) { for _ in 0..kw.len() { hl.push(Highlight::Keyword1); } i += kw.len(); found = true; break; } }
                if found { continue; }
                for kw in syntax.keywords2 { if s.starts_with(kw) && (kw.len() == s.len() || !rchars[i+kw.len()].is_alphanumeric()) { for _ in 0..kw.len() { hl.push(Highlight::Keyword2); } i += kw.len(); found = true; break; } }
                if found { continue; }
            }
            hl.push(Highlight::Normal); i += 1;
        }
        let changed = self.state.lines[idx].hl_open_comment != in_comm; self.state.lines[idx].hl = hl; self.state.lines[idx].hl_open_comment = in_comm; changed
    }
    fn update_all_hl(&mut self) { for i in 0..self.state.lines.len() { self.update_hl(i); } }
    fn render_cx(&self) -> usize { let mut rx = 0; for c in self.state.lines[self.state.cy].chars.chars().take(self.state.cx) { if c == '\t' { rx += 8 - (rx % 8); } else { rx += 1; } } rx }
    fn save_st(&mut self) { self.undo.push(self.state.clone()); self.redo.clear(); if self.undo.len() > 1000 { self.undo.remove(0); } }
}

struct Editor { buffers: Vec<Buffer>, cur: usize, rows: u16, cols: u16, msg: String, msg_t: Instant, _raw: RawMode }
struct RawMode { orig: Termios }
impl RawMode {
    fn enable() -> Self {
        let mut t = unsafe { std::mem::zeroed() }; unsafe { tcgetattr(0, &mut t) }; let orig = t;
        t.c_iflag &= !(0x400|0x100|0x2|0x10|0x20); t.c_oflag &= !1; t.c_cflag |= 0x30; t.c_lflag &= !(0x8|0x2|0x8000|0x1); t.c_cc[6] = 0; t.c_cc[5] = 1;
        unsafe { tcsetattr(0, 2, &t) }; RawMode { orig }
    }
}
impl Drop for RawMode { fn drop(&mut self) { unsafe { tcsetattr(0, 2, &self.orig) }; } }

impl Editor {
    fn buf(&self) -> &Buffer { &self.buffers[self.cur] }
    fn buf_mut(&mut self) -> &mut Buffer { &mut self.buffers[self.cur] }
    fn scroll(&mut self) {
        let rcx = self.buf().render_cx(); let (rows, cols) = (self.rows, self.cols); let b = self.buf_mut();
        if b.state.cy < b.row_off { b.row_off = b.state.cy; } if b.state.cy >= b.row_off + rows as usize { b.row_off = b.state.cy - rows as usize + 1; }
        if rcx < b.col_off { b.col_off = rcx; } if rcx >= b.col_off + cols as usize { b.col_off = rcx - cols as usize + 1; }
    }
    fn refresh(&mut self) -> io::Result<()> {
        self.scroll(); let mut out = Vec::new(); out.write_all(b"\x1b[?25l\x1b[H")?;
        for y in 0..self.rows {
            let fr = y as usize + self.buf().row_off;
            if fr >= self.buf().state.lines.len() {
                if self.buf().state.lines.len() == 1 && self.buf().state.lines[0].chars.is_empty() && y == self.rows/3 {
                    let w = "Kiro editor -- version 0.4.3"; let mut p = (self.cols as usize - w.len()) / 2;
                    if p > 0 { out.write_all(b"\x1b[37m~\x1b[39m")?; p -= 1; } for _ in 0..p { out.write_all(b" ")?; } out.write_all(w.as_bytes())?;
                } else { out.write_all(b"\x1b[37m~\x1b[39m")?; }
            } else {
                let r = &self.buf().state.lines[fr]; let chars: Vec<char> = r.render.chars().collect();
                let start = self.buf().col_off; let end = std::cmp::min(start + self.cols as usize, chars.len());
                let mut cur_hl = Highlight::Normal;
                for i in start..end {
                    let h = r.hl.get(i).copied().unwrap_or(Highlight::Normal);
                    if h != cur_hl { out.write_all(self.hl_color(h))?; cur_hl = h; } out.write_all(chars[i].to_string().as_bytes())?;
                }
                out.write_all(b"\x1b[39m\x1b[49m")?;
            }
            out.write_all(b"\x1b[K\r\n")?;
        }
        out.write_all(b"\x1b[7m")?;
        let s1 = format!("\"{}\" - {}/{} {}", self.buf().filename.as_deref().unwrap_or("[No Name]"), self.cur+1, self.buffers.len(), if self.buf().state.modified {"(modified)"} else {""});
        let s2 = format!("{} {}/{}", self.buf().syntax.map(|s| s.file_type).unwrap_or("plain"), self.buf().state.cy+1, self.buf().state.lines.len());
        let mut sl = s1.len(); out.write_all(s1.as_bytes())?;
        while sl < self.cols as usize { if self.cols as usize - sl == s2.len() { out.write_all(s2.as_bytes())?; break; } out.write_all(b" ")?; sl += 1; }
        out.write_all(b"\x1b[0m\r\n\x1b[K")?;
        if Instant::now().duration_since(self.msg_t) < Duration::from_secs(5) { out.write_all(self.msg.as_bytes())?; } else { out.write_all(b"Ctrl-? for help")?; }
        let cx = self.buf().render_cx() - self.buf().col_off + 1; let cy = self.buf().state.cy - self.buf().row_off + 1;
        out.write_all(format!("\x1b[{};{}H\x1b[?25h", cy, cx).as_bytes())?; io::stdout().write_all(&out)?; io::stdout().flush()?; Ok(())
    }
    fn hl_color(&self, h: Highlight) -> &[u8] {
        match h {
            Highlight::Normal => b"\x1b[39m", Highlight::Comment|Highlight::MultiLineComment => b"\x1b[90m",
            Highlight::Keyword1 => if matches!(self.buf().syntax.map(|s| s.file_type), Some("rust")|Some("python")) { b"\x1b[94m" } else { b"\x1b[33m" },
            Highlight::Keyword2 => if matches!(self.buf().syntax.map(|s| s.file_type), Some("rust")|Some("python")) { b"\x1b[93m" } else { b"\x1b[91m" },
            Highlight::String => b"\x1b[32m", Highlight::Number => b"\x1b[95m",
        }
    }
    fn move_cursor(&mut self, k: Key) {
        let (cy, cx) = (self.buf().state.cy, self.buf().state.cx);
        match k {
            Key::Up|Key::Ctrl('P') => if cy > 0 { self.buf_mut().state.cy -= 1; }
            Key::Down|Key::Ctrl('N') => if cy < self.buf().state.lines.len() - 1 { self.buf_mut().state.cy += 1; }
            Key::Left|Key::Ctrl('B') => if cx > 0 { self.buf_mut().state.cx -= 1; } else if cy > 0 { self.buf_mut().state.cy -= 1; self.buf_mut().state.cx = self.buf().state.lines[self.buf().state.cy].chars.chars().count(); }
            Key::Right|Key::Ctrl('F') => if cx < self.buf().state.lines[cy].chars.chars().count() { self.buf_mut().state.cx += 1; } else if cy < self.buf().state.lines.len() - 1 { self.buf_mut().state.cy += 1; self.buf_mut().state.cx = 0; }
            Key::Home|Key::Ctrl('A') => self.buf_mut().state.cx = 0,
            Key::End|Key::Ctrl('E') => self.buf_mut().state.cx = self.buf().state.lines[cy].chars.chars().count(),
            Key::PageUp => { let b = self.buf_mut(); b.state.cy = b.row_off; for _ in 0..self.rows { self.move_cursor(Key::Up); } }
            Key::PageDown => { let (rows, b) = (self.rows, self.buf_mut()); b.state.cy = std::cmp::min(b.row_off + rows as usize - 1, b.state.lines.len() - 1); for _ in 0..rows { self.move_cursor(Key::Down); } }
            _ => {}
        }
        let cur_len = self.buf().state.lines[self.buf().state.cy].chars.chars().count(); if self.buf_mut().state.cx > cur_len { self.buf_mut().state.cx = cur_len; }
    }
    fn insert_char(&mut self, c: char) {
        self.buf_mut().save_st(); let cy = self.buf().state.cy; let cx = self.buf().state.cx;
        if c == '\r' {
            let rest: String = self.buf().state.lines[cy].chars.chars().skip(cx).collect();
            self.buf_mut().state.lines[cy].chars = self.buf().state.lines[cy].chars.chars().take(cx).collect();
            self.buf_mut().state.lines[cy].update(); self.buf_mut().state.lines.insert(cy + 1, Row::new(rest)); self.buf_mut().state.cy += 1; self.buf_mut().state.cx = 0;
        } else {
            let mut chars: Vec<char> = self.buf().state.lines[cy].chars.chars().collect(); chars.insert(cx, c);
            self.buf_mut().state.lines[cy].chars = chars.into_iter().collect(); self.buf_mut().state.lines[cy].update(); self.buf_mut().state.cx += 1;
        }
        self.buf_mut().state.modified = true; self.buf_mut().update_all_hl();
    }
    fn delete_char(&mut self) {
        let cy = self.buf().state.cy; let cx = self.buf().state.cx; if cx == 0 && cy == 0 { return; }
        self.buf_mut().save_st();
        if cx > 0 { let mut chars: Vec<char> = self.buf().state.lines[cy].chars.chars().collect(); chars.remove(cx - 1); self.buf_mut().state.lines[cy].chars = chars.into_iter().collect(); self.buf_mut().state.lines[cy].update(); self.buf_mut().state.cx -= 1; }
        else { let prev_len = self.buf().state.lines[cy-1].chars.chars().count(); let cur_line = self.buf().state.lines[cy].chars.clone(); self.buf_mut().state.lines[cy-1].chars.push_str(&cur_line); self.buf_mut().state.lines[cy-1].update(); self.buf_mut().state.lines.remove(cy); self.buf_mut().state.cy -= 1; self.buf_mut().state.cx = prev_len; }
        self.buf_mut().state.modified = true; self.buf_mut().update_all_hl();
    }
    fn undo(&mut self) { let b = self.buf_mut(); if let Some(s) = b.undo.pop() { b.redo.push(b.state.clone()); b.state = s; b.update_all_hl(); } }
    fn redo(&mut self) { let b = self.buf_mut(); if let Some(s) = b.redo.pop() { b.undo.push(b.state.clone()); b.state = s; b.update_all_hl(); } }
    fn save(&mut self) { let b = self.buf_mut(); if let Some(ref n) = b.filename { if let Ok(mut f) = File::create(n) { for r in &b.state.lines { f.write_all(r.chars.as_bytes()).ok(); f.write_all(b"\n").ok(); } b.state.modified = false; } } }
}

fn read_key() -> Key {
    let mut b = [0u8; 1]; if io::stdin().read_exact(&mut b).is_err() { return Key::Unknown; }
    if b[0] == 0x1b {
        let mut n = [0u8; 1]; if io::stdin().read_exact(&mut n).is_err() { return Key::Esc; }
        if n[0] == b'[' {
            let mut s = [0u8; 2]; if io::stdin().read_exact(&mut s[0..1]).is_err() { return Key::Unknown; }
            if s[0] >= b'0' && s[0] <= b'9' { if io::stdin().read_exact(&mut s[1..2]).is_err() { return Key::Unknown; } if s[1] == b'~' { match s[0] { b'1'|b'7' => Key::Home, b'3' => Key::Delete, b'4'|b'8' => Key::End, b'5' => Key::PageUp, b'6' => Key::PageDown, _ => Key::Unknown } } else { Key::Unknown } }
            else { match s[0] { b'A' => Key::Up, b'B' => Key::Down, b'C' => Key::Right, b'D' => Key::Left, b'H' => Key::Home, b'F' => Key::End, _ => Key::Unknown } }
        } else { Key::Alt(n[0] as char) }
    } else if b[0] == 0x7f { Key::Backspace } else if b[0] < 32 { Key::Ctrl((b[0] + b'@') as char) }
    else {
        let mut bs = vec![b[0]]; let l = if b[0]<0x80 { 1 } else if b[0]<0xe0 { 2 } else if b[0]<0xf0 { 3 } else { 4 };
        for _ in 1..l { let mut n = [0u8; 1]; if io::stdin().read_exact(&mut n).is_ok() { bs.push(n[0]); } }
        if let Ok(s) = String::from_utf8(bs) { if let Some(c) = s.chars().next() { return Key::Char(c); } } Key::Unknown
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect(); let mut buffers = Vec::new();
    if args.is_empty() { buffers.push(Buffer::new(None)); } else {
        let mut help = false; for a in &args { if a == "--help" || a == "-h" { help = true; } if a == "--version" || a == "-v" { println!("0.4.3"); return; } }
        if help {
            println!("./executable: A tiny UTF-8 terminal text editor\n\nKiro is a tiny UTF-8 text editor on terminals for Unix-like systems.\nSpecify file paths to edit as a command argument or run without argument to\nstart to write a new text.\nHelp can show up with key mapping Ctrl-?.\n\nUsage:\n    ./executable [options] [FILES...]\n\nMappings:\n    Ctrl-Q                        : Quit\n    Ctrl-S                        : Save to file\n    Ctrl-O                        : Open text buffer\n    Ctrl-X                        : Next text buffer\n    Alt-X                         : Previous text buffer\n    Ctrl-P or UP                  : Move cursor up\n    Ctrl-N or DOWN                : Move cursor down\n    Ctrl-F or RIGHT               : Move cursor right\n    Ctrl-B or LEFT                : Move cursor left\n    Ctrl-A or Alt-LEFT or HOME    : Move cursor to head of line\n    Ctrl-E or Alt-RIGHT or END    : Move cursor to end of line\n    Ctrl-[ or Ctrl-V or PAGE DOWN : Next page\n    Ctrl-] or Alt-V or PAGE UP    : Previous page\n    Alt-F or Ctrl-RIGHT           : Move cursor to next word\n    Alt-B or Ctrl-LEFT            : Move cursor to previous word\n    Alt-N or Ctrl-DOWN            : Move cursor to next paragraph\n    Alt-P or Ctrl-UP              : Move cursor to previous paragraph\n    Alt-<                         : Move cursor to top of file\n    Alt->                         : Move cursor to bottom of file\n    Ctrl-H or BACKSPACE           : Delete character\n    Ctrl-D or DELETE              : Delete next character\n    Ctrl-W                        : Delete a word\n    Ctrl-J                        : Delete until head of line\n    Ctrl-K                        : Delete until end of line\n    Ctrl-U                        : Undo last change\n    Ctrl-R                        : Redo last undo change\n    Ctrl-G                        : Search text\n    Ctrl-M                        : New line\n    Ctrl-L                        : Refresh screen\n    Ctrl-?                        : Show this help\n\nOptions:\n    -v, --version       Print version\n    -h, --help          Print this help");
            return;
        }
        for a in args { buffers.push(Buffer::new(Some(a))); }
    }
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 }; unsafe { ioctl(1, TIOCGWINSZ, &mut ws) };
    let mut ed = Editor { buffers, cur: 0, rows: ws.ws_row - 2, cols: ws.ws_col, msg: String::new(), msg_t: Instant::now(), _raw: RawMode::enable() };
    loop {
        ed.refresh().ok(); let k = read_key();
        match k { Key::Ctrl('Q') => break, Key::Char(c) => ed.insert_char(c), Key::Backspace => ed.delete_char(), Key::Ctrl('S') => ed.save(), Key::Ctrl('U') => ed.undo(), Key::Ctrl('R') => ed.redo(), Key::Ctrl('X') => { let len = ed.buffers.len(); ed.cur = (ed.cur + 1) % len; }, Key::Alt('X')|Key::Alt('x') => { let len = ed.buffers.len(); ed.cur = (ed.cur + len - 1) % len; }, _ => ed.move_cursor(k) }
    }
}
